#!/usr/bin/env python3
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3]; KIT=ROOT/'catalog/kits/wind-energy'; B=Path(__file__).resolve().parent
idx=json.loads((ROOT/'catalog/index.json').read_text()); rows=[a for a in idx['assets'] if a['kit']=='wind-energy']; audit=json.loads((B/'asset-check-results.json').read_text())
lines=['# Wind energy kit','','Fifty original low-poly wind-farm turbine, grid and maintenance props. All sources use millimetres, Z up, base origin at z = 0 and editable `scale` and `color` controls. Audited exports range from %d to %d triangles, use one material and remain within their per-asset budgets.'%tuple(audit['triangleRange']),'','The [wind energy wave demo bundle](../../../artifacts/catalog-demos/wind-energy-wave-20261103/README.md) retains the generator, local audit evidence, rendered previews, page check, capture settings and visually inspected MP4. Local page generation was checked; deployed behavior remains unverified.','','| id | asset | description | knobs | triangles |','| --- | --- | --- | --- | ---: |']
for a in rows: lines.append(f"| `{a['id']}` | {a['title']} | {a['description']} | {' · '.join(p['name'] for p in a['params'])} | {a['stats']['triangles']} |")
lines += ['', '## Rebuild and verify','','```sh','python3 artifacts/catalog-demos/wind-energy-wave-20261103/generate_wind_assets.py','npx tsx scripts/buildAssetCatalog.ts','npx eslint catalog/','npx vitest run src/kernel/backends/occt/occtResetPoison.test.ts','npx vitest run tests/integration/catalog/','python3 artifacts/catalog-demos/wind-energy-wave-20261103/render_wind_previews.py','npx tsx scripts/buildCatalogPages.ts /tmp/kernelcad-wind-pages','python3 artifacts/catalog-demos/wind-energy-wave-20261103/verify_wind_pages.py /tmp/kernelcad-wind-pages','```','','## License and scope','','Every asset is dedicated to the public domain under [CC0 1.0](https://creativecommons.org/publicdomain/zero/1.0/). These are stylized scene props; they do not claim wind performance, structural loading, electrical generation, installation suitability or physical acceptance.','','See the demo README for current public-site status and verification limits.']
(KIT/'README.md').write_text('\n'.join(lines)+'\n');print('wrote README')
